INSERT INTO `category_description` (`id`, `categoryId`, `description`, `images`, `created_at`, `updated_at`) VALUES
(1, '33', NULL, '[{\"file_name\":\"1769755508_697c537401d0b.svg\",\"full_path\":\"category\\/1769755508_697c537401d0b.svg\",\"is_featured\":true}]', '2026-01-30 01:15:08', '2026-01-30 01:15:08'),
(2, '34', NULL, '[{\"file_name\":\"1769755583_697c53bfb3f62.svg\",\"full_path\":\"category\\/1769755583_697c53bfb3f62.svg\",\"is_featured\":true}]', '2026-01-30 01:16:23', '2026-01-30 01:16:23'),
(3, '35', NULL, '[{\"file_name\":\"1769755609_697c53d9708db.svg\",\"full_path\":\"category\\/1769755609_697c53d9708db.svg\",\"is_featured\":true}]', '2026-01-30 01:16:49', '2026-01-30 01:16:49'),
(4, '36', NULL, '[{\"file_name\":\"1769755633_697c53f1107df.svg\",\"full_path\":\"category\\/1769755633_697c53f1107df.svg\",\"is_featured\":true}]', '2026-01-30 01:17:13', '2026-01-30 01:17:13'),
(5, '37', NULL, '[{\"file_name\":\"1769755658_697c540ac7e86.svg\",\"full_path\":\"category\\/1769755658_697c540ac7e86.svg\",\"is_featured\":true}]', '2026-01-30 01:17:38', '2026-01-30 01:17:38'),
(6, '38', 'Clamshell Split-Frame Cutters and Accessories are precision pipe machining tools designed for accurate cutting, beveling, and facing of pipes in industrial environments. These portable, split-frame machines mount externally around the pipe, allowing safe and efficient in-line machining without removing the pipe from service. Ideal for industries such as oil & gas, power plants, and fabrication, they deliver high-performance results even in tight or restricted spaces. A full range of accessories is available to support different pipe sizes, materials, and machining requirements, ensuring flexibility and reliable operation on every job.', '[{\"file_name\":\"1769757875_697c5cb3a4f05.svg\",\"full_path\":\"category\\/1769757875_697c5cb3a4f05.svg\",\"is_featured\":true}]', '2026-01-30 01:54:35', '2026-01-30 01:54:35'),
(7, '39', 'I.D. Mount Pipe Bevelers are compact, high-precision tools designed to bevel, face, and prepare pipe ends from the inside diameter. Engineered for accuracy and stability, these machines expand internally to grip the pipe, making them ideal for applications where external access is limited. Commonly used in industries such as oil & gas, power generation, and shipbuilding, they ensure clean, consistent weld preparation with minimal setup time. A variety of accessories and tooling options allow compatibility with different pipe sizes, materials, and job-site requirements.', '[{\"file_name\":\"1769757929_697c5ce97e0d0.svg\",\"full_path\":\"category\\/1769757929_697c5ce97e0d0.svg\",\"is_featured\":true}]', '2026-01-30 01:55:29', '2026-01-30 01:55:29'),
(8, '40', 'Flange Facers are specialized machining tools used to restore, resurface, and recondition flange faces with high precision. Designed for both on-site and workshop use, these machines ensure smooth, accurate sealing surfaces that help prevent leaks and maintain system integrity. Suitable for a wide range of flange sizes and standards, they are widely used in industries such as oil & gas, petrochemical, and power generation. With versatile mounting options and accessories available, flange facers deliver reliable performance even in demanding field conditions.', '[{\"file_name\":\"1769757973_697c5d15c5403.svg\",\"full_path\":\"category\\/1769757973_697c5d15c5403.svg\",\"is_featured\":true}]', '2026-01-30 01:56:13', '2026-01-30 01:56:13'),
(9, '41', 'Torque Wrenches are precision tools designed to apply a specific amount of torque to fasteners, ensuring accurate and secure tightening. Essential for maintaining safety and performance, they help prevent over-tightening or under-tightening that can lead to equipment failure. Widely used in mechanical, automotive, industrial, and maintenance applications, torque wrenches provide consistent results and improved reliability. Available in various types and ranges, along with compatible accessories, they support a broad range of fastening requirements.', '[{\"file_name\":\"1769758031_697c5d4f9981f.svg\",\"full_path\":\"category\\/1769758031_697c5d4f9981f.svg\",\"is_featured\":true}]', '2026-01-30 01:57:11', '2026-01-30 01:57:11'),
(10, '42', 'Hydraulic Pumps are powerful units designed to generate controlled hydraulic pressure for operating tools, machinery, and lifting systems. Built for reliability and performance, they deliver consistent force for demanding industrial applications such as maintenance, construction, and heavy equipment servicing. Available in manual, electric, and pneumatic variants, hydraulic pumps support a wide range of hydraulic tools and systems. With durable construction and compatible accessories, they ensure efficient operation and dependable performance in tough working conditions.', '[{\"file_name\":\"1769758069_697c5d75e9aec.svg\",\"full_path\":\"category\\/1769758069_697c5d75e9aec.svg\",\"is_featured\":true}]', '2026-01-30 01:57:49', '2026-01-30 01:57:49'),
(11, '43', 'Pistol-Style Torque Wrenches are compact, high-performance fastening tools designed to deliver precise torque with improved handling and control. Their ergonomic pistol-grip design allows operators to work comfortably in tight or hard-to-reach areas while maintaining accuracy and safety. Commonly used in industrial maintenance, assembly, and heavy equipment applications, they help ensure consistent bolt tension and reduce operator fatigue. Compatible accessories and torque ranges make them suitable for a wide variety of fastening tasks across demanding job sites.', '[{\"file_name\":\"1769758094_697c5d8e0abff.svg\",\"full_path\":\"category\\/1769758094_697c5d8e0abff.svg\",\"is_featured\":true}]', '2026-01-30 01:58:14', '2026-01-30 01:58:14'),
(12, '44', 'Manual Torque Wrenches are reliable hand-operated tools designed to apply precise torque to fasteners, ensuring accurate and controlled tightening. They are essential for preventing damage caused by over-tightening or under-tightening, helping maintain equipment safety and performance. Widely used in maintenance, mechanical, and industrial applications, manual torque wrenches offer durability, ease of use, and consistent results without the need for power sources. Available in various torque ranges and drive sizes, they suit a broad range of fastening requirements.', '[{\"file_name\":\"1769758114_697c5da21db81.svg\",\"full_path\":\"category\\/1769758114_697c5da21db81.svg\",\"is_featured\":true}]', '2026-01-30 01:58:34', '2026-01-30 01:58:34'),
(13, '45', 'We offer a comprehensive range of high-quality industrial tools and equipment designed to deliver precision, durability, and dependable performance in demanding work environments. Engineered to meet professional standards, our products support maintenance, fabrication, installation, and repair operations across industries such as oil & gas, power generation, manufacturing, and construction. With robust construction and a wide selection of compatible accessories, our solutions are built to handle diverse applications while ensuring efficiency, safety, and long-term reliability.', '[{\"file_name\":\"1769758135_697c5db71dccc.svg\",\"full_path\":\"category\\/1769758135_697c5db71dccc.svg\",\"is_featured\":true}]', '2026-01-30 01:58:55', '2026-01-30 01:58:55'),
(14, '46', '<p>Hydro Test Units are specialized systems used to perform hydrostatic pressure testing on pipes, vessels, cylinders, and industrial components to verify strength and leak integrity. These units generate controlled high-pressure water flow to safely test equipment before commissioning or after maintenance. Built for reliability and precision, they are widely used in industries such as oil &amp; gas, power plants, construction, and manufacturing. Available in various pressure capacities and configurations, hydro test units ensure safe, accurate testing while meeting industry safety and compliance standards.</p>', '[{\"file_name\":\"1770031846_69808ae67d9fa.jpg\",\"full_path\":\"category\\/1770031846_69808ae67d9fa.jpg\",\"is_featured\":true}]', '2026-02-02 06:00:46', '2026-02-02 06:00:46'),
(15, '47', '<p>Nitrogen Booster Systems are high-pressure gas compression units designed to increase nitrogen pressure for testing, purging, charging, and industrial process applications. Engineered for safety and efficiency, these systems deliver clean, oil-free compressed nitrogen with precise pressure control. They are widely used in industries such as oil &amp; gas, power generation, aerospace, and manufacturing where reliable high-pressure gas supply is essential. Available in various pressure ratings and configurations, nitrogen booster systems ensure consistent performance and safe operation in demanding environments.</p>', '[{\"file_name\":\"1770031924_69808b3402807.jpg\",\"full_path\":\"category\\/1770031924_69808b3402807.jpg\",\"is_featured\":true}]', '2026-02-02 06:02:04', '2026-02-02 06:02:04'),
(16, '48', '<p>Flange Spreaders are specialized tools designed to safely and efficiently separate pipe flanges for maintenance, gasket replacement, and inspection tasks. Built to deliver controlled force without damaging flange surfaces, they improve safety and reduce downtime during disassembly operations. Commonly used in industries such as oil &amp; gas, petrochemical, and power generation, flange spreaders are suitable for a wide range of flange sizes and pressure classes. With hydraulic and mechanical options available, along with compatible accessories, they provide reliable performance in demanding industrial environments.</p>', '[{\"file_name\":\"1770032162_69808c22ce961.png\",\"full_path\":\"category\\/1770032162_69808c22ce961.png\",\"is_featured\":true}]', '2026-02-02 06:06:02', '2026-02-02 06:06:02'),
(17, '49', '<p>Flange Alignment Tools are precision devices designed to correct misalignment between pipe flanges during installation, assembly, and maintenance. They help bring bolt holes into proper position safely and accurately, reducing the risk of damage to components and improving joint integrity. Commonly used in industries such as oil &amp; gas, petrochemical, and power generation, these tools enhance safety, speed up assembly, and minimize downtime. Available in mechanical and hydraulic options with various sizes and capacities, flange alignment tools ensure efficient and reliable flange connection in demanding work environments.</p>', '[{\"file_name\":\"1770032241_69808c718d6d1.jpg\",\"full_path\":\"category\\/1770032241_69808c718d6d1.jpg\",\"is_featured\":true}]', '2026-02-02 06:07:21', '2026-02-02 06:07:21'),
(18, '50', '<p>Nut Splitters are powerful maintenance tools designed to safely remove seized, corroded, or over-tightened nuts without damaging the bolt threads. Using controlled mechanical or hydraulic force, they crack the nut for easy removal, reducing the need for cutting or grinding. Widely used in industries such as oil &amp; gas, construction, and heavy equipment maintenance, nut splitters improve safety, save time, and minimize equipment damage. Available in various sizes and force capacities, they provide a reliable solution for tough disassembly tasks in demanding environments.</p>', '[{\"file_name\":\"1770032302_69808cae21587.jpg\",\"full_path\":\"category\\/1770032302_69808cae21587.jpg\",\"is_featured\":true}]', '2026-02-02 06:08:22', '2026-02-02 06:08:22'),
(19, '51', '<p>Single Acting Series tools are hydraulic devices designed to deliver force in one direction using hydraulic pressure, with spring or load return. Built for strength, reliability, and precision, they are ideal for lifting, pushing, positioning, and maintenance tasks in industrial environments. Commonly used in construction, heavy equipment servicing, manufacturing, and plant maintenance, these units provide powerful performance in compact designs. Available in multiple capacities and stroke lengths, the single acting series ensures efficient operation and dependable results across a wide range of applications.</p>', '[{\"file_name\":\"1770032369_69808cf1a09c8.jpg\",\"full_path\":\"category\\/1770032369_69808cf1a09c8.jpg\",\"is_featured\":true}]', '2026-02-02 06:09:29', '2026-02-02 06:09:29'),
(20, '52', '<p>Double Acting Series tools are hydraulic devices engineered to provide controlled force in both extension and retraction through hydraulic pressure. This design allows precise push-and-pull operations, making them ideal for applications requiring greater control, faster cycling, and higher efficiency. Widely used in construction, heavy machinery maintenance, manufacturing, and industrial operations, these units deliver strong, consistent performance in demanding environments. Available in various capacities and stroke lengths, the double acting series ensures versatility, reliability, and accurate load control across a wide range of tasks.</p>', '[{\"file_name\":\"1770032414_69808d1e6e04c.webp\",\"full_path\":\"category\\/1770032414_69808d1e6e04c.webp\",\"is_featured\":true}]', '2026-02-02 06:10:14', '2026-02-02 06:10:14'),
(21, '53', '<p>Hydraulic Pumps are essential power units designed to generate and control hydraulic pressure for operating cylinders, torque tools, and other hydraulic equipment. Built for strength and consistent performance, they deliver the force required for lifting, pressing, tightening, and maintenance applications. Suitable for industrial, construction, and heavy equipment environments, hydraulic pumps are available in manual, electric, and pneumatic models to meet different operational needs. With durable construction and compatibility with a wide range of hydraulic systems, they ensure efficient, safe, and reliable operation in demanding conditions.</p>', '[{\"file_name\":\"1770032480_69808d60b308c.jpg\",\"full_path\":\"category\\/1770032480_69808d60b308c.jpg\",\"is_featured\":true}]', '2026-02-02 06:11:20', '2026-02-02 06:11:20'),
(22, '54', '<p>Other Products include a diverse range of industrial tools and equipment designed to support various maintenance, installation, and operational needs. Built with a focus on durability, precision, and performance, these products are suitable for demanding work environments across industries such as oil &amp; gas, construction, manufacturing, and power generation. With reliable construction and compatibility with multiple applications, our additional product offerings ensure efficient operations, improved safety, and long-term dependability on every job site.</p>', '[{\"file_name\":\"1770032529_69808d91544b9.jpg\",\"full_path\":\"category\\/1770032529_69808d91544b9.jpg\",\"is_featured\":true}]', '2026-02-02 06:12:09', '2026-02-02 06:12:09');

